import {albums,members,roles} from './data.js';
import {rankMembers} from './matching.js';
import {artistCatalog,normalizeArtist} from './artists.js';
import {musicArt} from './music-art.js';
import {rotationPosts,rotationFeed} from './rotation.js';
const key='slug-collective-demo-v1';
const defaults=()=>({joined:false,profile:{name:'',bio:'',favorites:[],artists:[],roles:[],intent:'',provider:''},conversations:{},rotationPost:null,reactions:[]});
let state;try{state=JSON.parse(localStorage.getItem(key))||defaults();if(!state.profile||!Array.isArray(state.profile.favorites)||!state.conversations)state=defaults();}catch{state=defaults();}
state.profile.artists ??= state.profile.favorites.map(id=>albums[id]?.artist).filter(Boolean);
state.reactions ??= [];
let mobileChatOpen=false,threadScroll=0;
let artistQuery='';
let tab='people',filter='All people',query='',activeChat=null,step=0;
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>{const paths={like:'<path d="M7 10v11H3V10h4Zm0 0 5-8c2 0 3 2 2 5l-1 3h6a2 2 0 0 1 2 2l-2 7a3 3 0 0 1-3 2H7"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2m2-15a3 3 0 0 1 0 6m1 3a6 6 0 0 1 3 6"/>',create:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',inbox:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2v-9.5A8.5 8.5 0 0 1 10.5 4H13a8 8 0 0 1 8 7.5Z"/><path d="M7 10h9M7 14h6"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',music:'<path d="M9 18V5l11-2v13M9 8l11-2"/><ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="17" cy="16" rx="3" ry="2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',send:'<path d="m3 3 18 9-18 9 4-9-4-9Zm4 9h14"/>',link:'<path d="m9 15 6-6m-7 4-2 2a4 4 0 0 0 6 6l3-3m1-7 2-2a4 4 0 0 0-6-6L9 6"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.create}</svg>`;};
const brand=()=>`<a class="brand" href="#" data-action="home" aria-label="Slug Collective home"><svg class="slug" viewBox="0 0 50 40" aria-hidden="true"><path d="M7 30c5-1 7-4 10-10 3-7 9-10 16-7 5 2 7 8 7 13l5 4c-9 5-30 7-38 0Z" fill="currentColor" stroke="none"/><path d="m31 14-1-8m7 10 3-8"/><circle cx="30" cy="5" r="2" fill="currentColor"/><circle cx="41" cy="7" r="2" fill="currentColor"/></svg><span>slug collective<small>UC SANTA CRUZ</small></span></a>`;
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{toast('Browser storage is unavailable. Changes will last for this visit.');}}
let toastTimer;function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('toast-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('toast-visible'),3200);}
function artwork(id,cls=''){const a=albums[id];return `<img class="${cls}" src="${a.art}" alt="Original demo artwork for ${esc(a.title)}" loading="lazy">`;}
function picker(){return `<section class="artist-picker"><label for="artist-search">Who do you listen to?</label><p class="small muted">Search the demo artists or add anyone. No preset favorites list.</p><div class="artist-search">${icon('search')}<input id="artist-search" type="search" maxlength="80" placeholder="That artist nobody else seems to know…" aria-label="Search or add an artist" value="${esc(artistQuery)}"></div><div id="artist-results">${artistResults()}</div><div id="artist-selected">${selectedArtists()}</div><p class="small muted">Sample catalog, not live Spotify search. Artists you add stay on your profile; a match appears only when another member shares them.</p></section>`;}
function selectedArtists(){return `<p class="artist-count">${state.profile.artists.length} artists on your profile</p><div class="artist-selected">${state.profile.artists.map(a=>`<button type="button" class="artist-pill" data-action="remove-artist" data-artist="${esc(a)}" aria-label="Remove ${esc(a)}">${esc(a)} ×</button>`).join('')||'<span class="small muted">Your artists will show up here.</span>'}</div>`;}
function artistResults(){const q=normalizeArtist(artistQuery);if(!q)return '<p class="small muted">Type an artist’s name to start.</p>';const found=artistCatalog.filter(a=>normalizeArtist(a).includes(q)&&!state.profile.artists.some(v=>normalizeArtist(v)===normalizeArtist(a))).slice(0,7);const exact=artistCatalog.some(a=>normalizeArtist(a)===q)||state.profile.artists.some(a=>normalizeArtist(a)===q);return `<div class="artist-results">${found.map(a=>`<button type="button" class="artist-option" data-action="add-artist" data-artist="${esc(a)}"><span>${esc(a)}</span><small>+ add</small></button>`).join('')}${!exact?`<button type="button" class="artist-option" data-action="add-artist" data-artist="${esc(artistQuery.trim())}"><span>Add “${esc(artistQuery.trim())}”</span><small>Not in the sample catalog</small></button>`:''}${!found.length&&exact?'<p class="small muted">Already on your profile.</p>':''}</div>`;}
function updateArtistPicker(){document.querySelector('#artist-results').innerHTML=artistResults();document.querySelector('#artist-selected').innerHTML=selectedArtists();}
function onboarding(){app.innerHTML=`<div class="onboard"><section class="onboard-story">${brand()}<div><div class="eyebrow">SLUG COLLECTIVE / UCSC</div><h1>Someone here<br>listens to <em>them too.</em></h1><p class="sub">For the people you keep seeing at shows but haven’t met yet.</p><div class="art-stack">${artwork(0)}${artwork(2)}${artwork(4)}</div></div><p class="small muted">An independent creative space for the Slug Collective.</p></section><section class="onboard-form"><div class="steps" aria-label="Step ${step+1} of 3">${[0,1,2].map(n=>`<i class="${n<=step?'active':''}"></i>`).join('')}</div>${step===0?`<div class="eyebrow">STUDENT-RUN. OPEN TO YOU.</div><h2>Come hang.</h2><p class="muted">Meet other Slugs through the music you actually listen to.</p><form id="name-form"><label for="name">What should we call you?</label><input class="field" id="name" name="name" required maxlength="40" autocomplete="given-name" placeholder="Your first name" value="${esc(state.profile.name)}"><button class="primary" type="submit">Let’s go ${icon('arrow')}</button></form><p class="small muted">Interactive demo · no account or email needed.</p>`:step===1?`<div class="eyebrow">HEY, ${esc(state.profile.name)}</div><h2>Bring your music.</h2><p class="muted">The deep cuts count. Your listening history will help you find the people who get it.</p><button class="provider" data-action="provider" data-provider="Spotify">${icon('music')} Connect Spotify <span>↗</span></button><button class="provider" data-action="provider" data-provider="Apple Music">${icon('music')} Connect Apple Music <span>↗</span></button><p class="small muted">Demo connections only. No sign-in or listening data is requested. These buttons load a sample listening profile.</p><button class="primary" data-action="choose">Add artists myself ${icon('arrow')}</button><button class="text-button" data-action="join">Skip for now — just let me explore</button><br><button class="text-button" data-action="back-onboard">Back</button>`:`<div class="eyebrow">YOUR ROTATION</div><h2>Who’s in your headphones?</h2><p class="small muted">The small artists. The longtime favorites. Whoever you keep coming back to.</p>${picker()}<button class="primary" data-action="join">Find my people ${icon('arrow')}</button><button class="text-button" data-action="back-onboard">Back</button>`}</section></div>`;}
function render(){app.classList.toggle('inbox-view',state.joined&&tab==='inbox');if(!state.joined){onboarding();return;}app.innerHTML=`<aside class="sidebar">${brand()}<nav aria-label="Main navigation">${[['people','People'],['create','Create'],['inbox','Inbox'],['profile','Profile']].map(([id,label])=>`<button class="nav ${tab===id?'active':''}" data-action="tab" data-tab="${id}" ${tab===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-foot"><div class="mini-profile"><span class="initial">${esc(state.profile.name[0]?.toUpperCase()||'S')}</span><span>${esc(state.profile.name)}<br><span class="small muted">Member of the collective</span></span></div></div></aside><div class="shell"><header class="topbar"><div class="mobile-brand">${brand()}</div><span class="demo-badge">DEMO</span></header><main id="main">${tab==='people'||tab==='create'?discovery():tab==='inbox'?inbox():profile()}</main></div>`;}
function discovery(){const create=tab==='create';return `<section class="discovery-intro"><h1>${create?'Make something <em>together.</em>':'You listen to <em>them too?</em>'}</h1><p>${create?'Find someone to work with. See what happens.':'Meet other Slugs through shared music.'}</p></section><div class="toolbar compact-toolbar"><div class="filters" aria-label="${create?'Creative role':'People'} filters">${(create?['All creatives','Production','Vocals','Photography','Design','Film']:['All people','On repeat','Shared taste']).map(f=>`<button class="chip ${filter===f?'active':''}" data-action="filter" data-filter="${f}" aria-pressed="${filter===f}">${f}</button>`).join('')}${create?`<select id="role-filter" aria-label="More creative roles"><option value="">More roles</option>${roles.filter(r=>!['Production','Vocals','Photography','Design','Film'].includes(r)).map(r=>`<option ${filter===r?'selected':''}>${r}</option>`).join('')}</select>`:`<button class="share-record" data-action="share-record">+ Share a record</button>`}</div><label class="search" style="margin:0">${icon('search')}<input id="search" type="search" placeholder="${create?'People, skills…':'People, music…'}" aria-label="Search ${create?'creatives':'members'}" value="${esc(query)}"></label></div><div id="results">${results()}</div><p class="footer-note">Demo members & posts · Independent of UC Santa Cruz <button class="text-button" data-action="edit-profile">Edit your artists</button></p>`;}
function musicImage(artist){const a=musicArt[normalizeArtist(artist)];return a?`<img src="${esc(a.art)}" alt="${esc(a.title)} album cover by ${esc(a.artist)}" loading="lazy">`:`<div class="cover-placeholder" aria-label="No album cover available">${icon('music')}</div>`;}
function recordLabel(artist){const a=musicArt[normalizeArtist(artist)];return a?`${a.title} · ${a.artist}`:artist;}
function openShare(){modal.setAttribute('aria-label','Share a record');modal.innerHTML=`<button class="close" data-action="close" aria-label="Close share form">${icon('close')}</button><h2>What’s on repeat?</h2><p class="small muted">A record and a thought. Your demo post stays in this browser.</p><form id="rotation-form"><label for="post-artist">Artist</label><input id="post-artist" class="field" name="artist" list="post-artists" required maxlength="80" value="${esc(state.rotationPost?.artist||'')}"><datalist id="post-artists">${artistCatalog.map(a=>`<option value="${esc(a)}"></option>`).join('')}</datalist><label for="post-title">Record or song</label><input id="post-title" name="title" class="field" maxlength="100" required value="${esc(state.rotationPost?.title||'')}"><label for="post-note">Anything to add? <span class="muted">optional</span></label><textarea id="post-note" name="note" class="field" maxlength="220" placeholder="The track you keep coming back to…">${esc(state.rotationPost?.note||'')}</textarea><button class="primary" style="margin-top:20px" type="submit">Share to On repeat</button></form>`;modal.showModal();}
function rotationCard(post){const own=post.memberId===null,m=own?null:members[post.memberId],a=musicArt[normalizeArtist(post.artist)];const title=post.title||a?.title||post.artist;const cover=a&&normalizeArtist(title)===normalizeArtist(a.title);const liked=state.reactions.includes(post.id),likeCount=liked?1:0;return `<article class="card rotation-card"><div class="card-top">${own?`<span class="initial">${esc(state.profile.name[0]||'S')}</span>`:`<img class="avatar" src="${m.avatar}" alt="Illustrated portrait of ${m.name}">`}<button class="identity" data-action="${own?'edit-profile':'member'}" ${own?'':`data-id="${m.id}"`}><strong>${esc(own?state.profile.name:m.name)}</strong><small>${own?'Your post · saved locally':'Sample post'}</small></button></div><div class="record-cover">${cover?musicImage(post.artist):`<div class="cover-placeholder">${icon('music')}</div>`}</div><div class="card-body"><h2 class="record-title">${esc(title)}</h2><p class="artist">${esc(post.artist)}</p>${post.note?`<p class="post-note">${esc(post.note)}</p>`:''}<div class="post-actions"><button class="like-button ${liked?'active':''}" data-action="like" data-post="${post.id}" aria-pressed="${liked}" aria-label="${liked?'Unlike':'Like'} record by ${esc(post.artist)}; ${likeCount} ${likeCount===1?'like':'likes'}">${icon('like')}<span>${liked?'Liked':'Like'}</span><span class="like-count">${likeCount}</span></button>${own?`<button class="say" data-action="share-record">Edit post</button>`:`<button class="say" data-action="hey" data-id="${m.id}" data-context="${esc(title+' by '+post.artist+(post.note?' — '+post.note:''))}">Say hey ${icon('inbox')}</button>`}</div></div></article>`;}
function visible(){return rankMembers(members,state.profile,tab).filter(m=>{if(tab==='people'&&filter==='Shared taste'&&!m.sharedArtists.length)return false;if(tab==='people'&&filter==='Something new'&&m.sharedArtists.length)return false;if(tab==='create'&&filter!=='All creatives'&&!m.roles.includes(filter))return false;return [m.name,...m.roles,...m.artists,m.intent,...m.albums.flatMap(id=>[albums[id].title,albums[id].artist])].join(' ').toLowerCase().includes(query.toLowerCase().trim());});}
function results(){if(tab==='people'&&filter==='On repeat'){const posts=rotationFeed(rotationPosts.map(p=>({...p,title:musicArt[normalizeArtist(p.artist)]?.title||p.artist,author:members[p.memberId].name})),state.rotationPost?{...state.rotationPost,author:state.profile.name}:null,query);return `<div class="section-label"><span>${posts.length} ${posts.length===1?'post':'posts'} · sample activity + your local post</span></div><div class="grid">${posts.length?posts.map(rotationCard).join(''):'<div class="empty">No records found. Try another artist.</div>'}</div>`;}const list=visible();return `<div class="section-label"><span>${list.length} ${tab==='create'?'creatives':'people'}</span></div><div class="grid">${list.length?list.map(card).join(''):`<div class="empty"><h2>${filter==='Shared taste'&&!state.profile.artists.length?'Add your artists to find shared taste.':'No matches here yet.'}</h2><button class="secondary" data-action="${filter==='Shared taste'&&!state.profile.artists.length?'edit-profile':'clear'}">${filter==='Shared taste'&&!state.profile.artists.length?'Add artists':'Clear filters'}</button></div>`}</div>`;}
function reason(m){if(tab==='create'&&m.complements.length)return `Your ${m.pairs[0].yours.toLowerCase()} + their ${m.pairs[0].theirs.toLowerCase()}`;return m.sharedArtists.length?`You both listen to ${m.sharedArtists[0]}`:'Something new for you';}
function card(m){const create=tab==='create',shared=m.sharedArtists;const artist=shared[0]||m.artists[1];const others=m.artists.filter(a=>normalizeArtist(a)!==normalizeArtist(artist)).slice(0,3);return `<article class="card"><div class="card-top"><img class="avatar" src="${m.avatar}" alt="Illustrated portrait of ${m.name}" loading="lazy"><button class="identity" data-action="member" data-id="${m.id}"><strong>${m.name}</strong><small>${m.college} · ${m.pronouns}</small></button><button class="arrow" data-action="member" data-id="${m.id}" aria-label="View ${m.name}'s profile">${icon('arrow')}</button></div>${!create?`<div class="record-cover">${musicImage(artist)}<span class="cover-caption">${shared.length?'You both listen to':'Listening to'}</span></div>`:''}<div class="card-body">${create?`<div class="role-tags">${m.roles.map(r=>`<span class="role-tag">${r}</span>`).join('')}</div><p class="intent">${esc(m.intent)}</p>${m.work?`<button class="work-preview" data-action="work" data-id="${m.id}">${artwork(m.albums[0])}<span>${m.work}<small>Demo project</small></span>${icon('arrow')}</button>`:'<p class="small muted">No work posted yet.</p>'}<p class="shared">${esc(reason(m))}</p>`:`<h2 class="listening-artist">${esc(artist)}</h2><p class="cover-credit">${esc(musicArt[normalizeArtist(artist)]?.title||'')}</p><p class="other-artists">Also ${others.map(esc).join(' · ')}</p>`}<button class="say" data-action="hey" data-id="${m.id}" data-context="${esc(create?(m.work||m.intent):recordLabel(artist))}">Say hey ${icon('inbox')}</button></div></article>`;}
function openMember(id){const m=members[id];modal.setAttribute('aria-label',m.name+' profile');modal.innerHTML=`<button class="close" data-action="close" aria-label="Close profile">${icon('close')}</button><div class="modal-profile"><img class="avatar" src="${m.avatar}" alt="Illustrated portrait"><div><h2>${m.name}</h2><span class="small muted">${m.pronouns} · ${m.college}</span></div></div><p>${esc(m.bio)}</p><div class="role-tags">${m.roles.map(r=>`<span class="role-tag">${r}</span>`).join('')}</div><p class="small muted">WHAT THEY LISTEN TO</p><div class="taste-list">${m.artists.map(a=>`<span class="taste-tag ${state.profile.artists.some(v=>normalizeArtist(v)===normalizeArtist(a))?'is-shared':''}">${esc(a)}</span>`).join('')}</div><p class="small muted">ALBUMS</p><div class="modal-albums">${m.albums.map(id=>`<div>${artwork(id)}<p>${albums[id].title}<br><span class="muted">${albums[id].artist}</span></p></div>`).join('')}</div><p class="small muted">OPEN TO</p><p>${m.intent}</p>${m.work?`<button class="work-preview" data-action="work" data-id="${m.id}">${artwork(m.albums[0])}<span>${m.work}<small>Explore a work concept</small></span>${icon('arrow')}</button>`:''}<button style="margin-top:20px;width:100%" class="primary" data-action="hey" data-id="${m.id}" data-context="${esc(tab==='create'?(m.work||m.intent):(m.artists.find(a=>state.profile.artists.some(v=>normalizeArtist(v)===normalizeArtist(a)))||m.artists[1]))}">Say hey ${icon('inbox')}</button>`;modal.showModal();}
function openWork(id){const m=members[id];modal.setAttribute('aria-label',m.work+' work concept');modal.innerHTML=`<button class="close" data-action="close" aria-label="Close work preview">${icon('close')}</button><p class="eyebrow">WORK CONCEPT · ${m.name}</p>${artwork(m.albums[0],'work-art')}<h2>${m.work}</h2><p>${m.workDescription}</p><p class="small muted">This prototype shows a fictional work concept. Audio, video, and file uploads will come in a later version.</p><button class="primary" data-action="hey" data-id="${m.id}" data-context="${esc(m.work)}">Ask about this ${icon('inbox')}</button>`;if(!modal.open)modal.showModal();}
function startChat(id,context){const old=state.conversations[id];if(!old)state.conversations[id]={context,messages:[]};else if(context)old.context=context;activeChat=id;mobileChatOpen=true;tab='inbox';save();modal.close();render();document.querySelector('#message')?.focus();}
function inbox(){const entries=Object.entries(state.conversations);if(activeChat===null&&entries.length)activeChat=Number(entries[0][0]);const m=members[activeChat],c=state.conversations[activeChat];return `<h1 class="sr-only">Inbox</h1>${!entries.length?`<div class="empty"><h2>No messages yet.</h2><p>Find someone who listens to your artists and say hey.</p><button class="primary" data-action="tab" data-tab="people">Meet the collective ${icon('arrow')}</button></div>`:`<div class="inbox-layout ${mobileChatOpen?'is-chat-open':''}"><div class="threads" aria-label="Conversations"><h2 class="threads-title">Chats</h2>${entries.map(([id,v])=>`<button class="thread ${Number(id)===activeChat?'active':''}" data-action="thread" data-id="${id}"><img class="avatar" src="${members[id].avatar}" alt=""><span>${members[id].name}<small>${esc(v.messages.at(-1)?.text||'Start with a little hello')}</small></span></button>`).join('')}</div><section class="chat" aria-label="Conversation with ${m.name}"><div class="chat-head"><button class="chat-back" data-action="inbox-back" aria-label="Back to chats">${icon('arrow')}</button><div class="chat-heading"><strong>${m.name}</strong><small>Demo conversation</small></div></div><div class="messages" aria-live="polite"><div class="context">Talking about: ${esc(c.context)}</div>${!c.messages.length?`<p class="small muted">Ask how they found the artist, or what track you should hear next.</p>`:c.messages.map(v=>`<div class="message ${v.from==='me'?'me':''}"><span class="sr-only">${v.from==='me'?'You':m.name}: </span>${esc(v.text)}</div>`).join('')}</div><form class="compose" id="message-form"><input id="message" aria-label="Message ${m.name}" placeholder="Say something nice…" required maxlength="1000" autocomplete="off"><button class="primary" type="submit" aria-label="Send message">${icon('send')}</button></form></section></div>`}`;}
function profile(){return `<h1 class="sr-only">Profile</h1><form id="profile-form" class="profile-form profile-editor"><section class="profile-section about-section"><div class="profile-section-head"><div class="profile-avatar">${esc(state.profile.name[0]?.toUpperCase()||'S')}</div><div><h2>About you</h2></div></div><div class="about-fields"><div><label for="profile-name">Name</label><input id="profile-name" class="field" name="name" required maxlength="40" value="${esc(state.profile.name)}" autocomplete="given-name"></div><div><label for="bio">Bio <span class="optional">optional</span></label><textarea id="bio" name="bio" class="field" maxlength="300" placeholder="What should people know about you?">${esc(state.profile.bio)}</textarea></div></div></section><section class="profile-section music-section"><div class="section-heading"><h2>Your music</h2><span class="connection-label">${state.profile.provider?esc(state.profile.provider)+' · demo':'Added by you'}</span></div><p class="section-description">The artists that help you find your people.</p>${compactPicker()}</section><section class="profile-section creative-section"><div class="section-heading"><h2>Creative side</h2><span class="optional">optional</span></div><p class="section-description">Show up in Create with the things you do.</p><label id="roles-label">What do you make?</label><div class="role-picker" role="group" aria-labelledby="roles-label">${roles.map(r=>`<button class="chip ${state.profile.roles.includes(r)?'active':''}" type="button" data-action="role" data-role="${r}" aria-pressed="${state.profile.roles.includes(r)}">${r}</button>`).join('')}</div><label for="intent">Open to</label><input id="intent" name="intent" class="field" maxlength="160" value="${esc(state.profile.intent)}" placeholder="A band, cover art, casual jams…"></section><div class="profile-save"><button type="submit" class="primary">Save profile ${icon('arrow')}</button></div><details class="demo-details"><summary>About this demo</summary><p>Changes stay in this browser. Music connections, members, and conversations are simulated.</p><button class="text-button" type="button" data-action="reset">Reset this demo</button></details></form>`;}
function compactPicker(){return `<div class="artist-picker"><label for="artist-search">Add an artist</label><div class="artist-search">${icon('search')}<input id="artist-search" type="search" maxlength="80" placeholder="Search or add anyone…" aria-label="Search or add an artist" value="${esc(artistQuery)}"></div><div id="artist-results">${artistResults()}</div><div id="artist-selected">${selectedArtists()}</div><p class="picker-footnote">Demo catalog. You can add artists outside it, too.</p></div>`;}
function captureProfile(){if(tab==='profile'&&state.joined){const f=document.querySelector('#profile-form');if(f){state.profile.name=f.elements.name.value;state.profile.bio=f.elements.bio.value;state.profile.intent=f.elements.intent.value;}}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=Number(b.dataset.id);if(a==='home'){e.preventDefault();if(state.joined){tab='people';query='';filter='All people';render();}return;}if(a==='tab'){captureProfile();tab=b.dataset.tab;if(tab==='inbox')mobileChatOpen=false;query='';filter=tab==='create'?'All creatives':'All people';render();document.querySelector('.nav.active')?.focus();window.scrollTo(0,0);}if(a==='provider'){state.profile.provider=b.dataset.provider;state.profile.favorites=[];state.profile.artists=b.dataset.provider==='Spotify'?['feeble little horse','Duster','Dean Blunt']:['Tirzah','Liv.e','Grouper'];state.joined=true;save();render();toast(`${b.dataset.provider} demo ready — sample listening profile loaded.`);}if(a==='choose'){step=2;onboarding();window.scrollTo(0,0);}if(a==='back-onboard'){step=Math.max(0,step-1);onboarding();}if(a==='join'){state.joined=true;save();render();window.scrollTo(0,0);}if(a==='add-artist'){captureProfile();const artist=b.dataset.artist.trim().replace(/\s+/g,' ');if(artist&&!state.profile.artists.some(v=>normalizeArtist(v)===normalizeArtist(artist)))state.profile.artists.push(artist);artistQuery='';document.querySelector('#artist-search').value='';updateArtistPicker();save();document.querySelector('#artist-search').focus();}if(a==='remove-artist'){captureProfile();state.profile.artists=state.profile.artists.filter(v=>normalizeArtist(v)!==normalizeArtist(b.dataset.artist));updateArtistPicker();save();document.querySelector('#artist-search').focus();}if(a==='album'){captureProfile();const p=state.profile.favorites;p.includes(id)?p.splice(p.indexOf(id),1):p.push(id);b.classList.toggle('selected',p.includes(id));b.setAttribute('aria-pressed',p.includes(id));if(state.joined)save();}if(a==='role'){captureProfile();const p=state.profile.roles,r=b.dataset.role;p.includes(r)?p.splice(p.indexOf(r),1):p.push(r);b.classList.toggle('active',p.includes(r));b.setAttribute('aria-pressed',p.includes(r));save();}if(a==='share-record'){openShare();}if(a==='like'){const post=b.dataset.post;state.reactions.includes(post)?state.reactions=state.reactions.filter(v=>v!==post):state.reactions.push(post);save();document.querySelector('#results').innerHTML=results();document.querySelector(`[data-post="${post}"]`)?.focus();}if(a==='filter'){filter=b.dataset.filter;render();document.querySelector('.chip.active')?.focus();}if(a==='clear'){query='';filter=tab==='create'?'All creatives':'All people';render();}if(a==='member')openMember(id);if(a==='work')openWork(id);if(a==='close')modal.close();if(a==='hey')startChat(id,b.dataset.context);if(a==='thread'){threadScroll=document.querySelector('.threads')?.scrollTop||0;activeChat=id;mobileChatOpen=true;render();if(window.innerWidth<=700)document.querySelector('.chat-back')?.focus();}if(a==='inbox-back'){mobileChatOpen=false;render();const list=document.querySelector('.threads');if(list)list.scrollTop=threadScroll;document.querySelector('.thread.active')?.focus({preventScroll:true});}if(a==='edit-profile'){tab='profile';render();}if(a==='reset'){modal.setAttribute('aria-label','Reset demo');modal.innerHTML=`<h2>A fresh start?</h2><p>This clears your profile and demo conversations from this browser.</p><button class="primary" data-action="confirm-reset">Reset demo</button> <button class="secondary" data-action="close">Keep hanging</button>`;modal.showModal();}if(a==='confirm-reset'){state=defaults();step=0;tab='people';query='';filter='All people';activeChat=null;save();modal.close();render();}});
document.addEventListener('input',e=>{if(e.target.id==='artist-search'){artistQuery=e.target.value;document.querySelector('#artist-results').innerHTML=artistResults();}if(e.target.id==='search'){query=e.target.value;document.querySelector('#results').innerHTML=results();}});
document.addEventListener('change',e=>{if(e.target.id==='post-artist'){const art=musicArt[normalizeArtist(e.target.value)];if(art)document.querySelector('#post-title').value=art.title;}if(e.target.id==='role-filter'&&e.target.value){filter=e.target.value;render();}});
document.addEventListener('submit',e=>{if(e.target.id==='rotation-form'){e.preventDefault();const f=e.target.elements;const artist=f.artist.value.trim(),title=f.title.value.trim();if(!artist||!title)return;state.rotationPost={artist,title,note:f.note.value.trim(),createdAt:Date.now()};save();modal.close();tab='people';filter='On repeat';query='';render();window.scrollTo(0,0);toast('Record shared in this demo.');}if(e.target.id==='name-form'){e.preventDefault();const name=e.target.elements.name.value.trim();if(!name)return;state.profile.name=name;step=1;onboarding();window.scrollTo(0,0);}if(e.target.id==='profile-form'){e.preventDefault();if(document.activeElement?.id==='artist-search')return;captureProfile();state.profile.name=state.profile.name.trim();if(!state.profile.name){toast('Add a name so people know what to call you.');return;}save();toast('Profile saved.');}if(e.target.id==='message-form'){e.preventDefault();const text=e.target.elements.message.value.trim();if(!text)return;const c=state.conversations[activeChat];c.messages.push({from:'me',text});c.messages.push({from:'them',text:c.messages.length===1?'Hey! So glad you reached out. Always down to talk music and make something together. (Demo reply)':'Love that. Let’s keep this idea going! (Demo reply)'});save();render();const messages=document.querySelector('.messages');messages.scrollTop=messages.scrollHeight;document.querySelector('#message').focus();}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
render();
